from pathlib import Path
import json,hashlib,subprocess,datetime
root=Path(__file__).resolve().parent
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
paths=['src/cloth_bending.hpp','src/cloth_bending.cpp','src/register_types.cpp','CMakeLists.txt','build_profile.json','project/native_cloth_bending.gdextension','project/bin/native_cloth_bending.windows.release.x86_64.dll','extension_api.json','gdextension_interface.h','project/fixtures/skirt-cage-schema2.json','reports/native-bending-verification.json']
api=json.loads((root/'extension_api.json').read_text(encoding='utf-8'))['header']
data={'schema':'dafeiyu.native-cloth-bending.manifest.v1','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Standalone technical archive; native character art is frozen/rejected, no renderer/GLB/DSH modification or promotion.','native_class':'NativeClothBending','ref_counted':True,'files':{p:{'sha256':sha(root/p),'bytes':(root/p).stat().st_size}for p in paths},'godot_api':api,'godot_cpp':{'repository':'https://github.com/godotengine/godot-cpp','tag':'10.0.0-stable','commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root/'vendor/godot-cpp',text=True).strip(),'source_unchanged':not bool(subprocess.check_output(['git','status','--short'],cwd=root/'vendor/godot-cpp',text=True).strip())},'toolchain':{'compiler':'Installed Microsoft MSVC 19.50.35723 x64','cmake':'Installed Microsoft-bundled CMake 4.1.1-msvc1','windows_sdk':'10.0.26100.0','global_PATH_modified':False,'new_compiler_installed':False},'verification':json.loads((root/'reports/native-bending-verification.json').read_text(encoding='utf-8')),'limitations':['No live Jolt integration/stress or GPU benchmark.','Forces only; Jolt remains responsible for integration and collision.','Energy metric remains the uncapped quadratic diagnostic while material moment is capped.','Win64 official single-precision ABI only.']}
(root/'reports/component-manifest.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'dll_sha256':data['files'][paths[6]]['sha256'],'manifest':str(root/'reports/component-manifest.json'),'godot_cpp_source_unchanged':data['godot_cpp']['source_unchanged']}))
